<?php
declare(strict_types=1);
final class PostTaskContinuationRepository implements PostTaskContinuationStoreInterface{
 public function __construct(private mysqli$db){}
 public function enrollRoot(int$u,int$p,string$taskPublic,string$cyclePublic):array{$this->db->begin_transaction();try{$s=$this->p("SELECT t.id_ task_id,c.id_ cycle_id,c.status cycle_status,ap.mode,ap.status policy_status FROM Tasks t JOIN Projects pr ON pr.id_=t.project_id_ AND pr.user_id_=t.user_id_ JOIN ProjectAutonomyCycles c ON c.project_id_=pr.id_ AND c.user_id_=t.user_id_ JOIN ProjectAutonomyPolicies ap ON ap.id_=c.policy_id_ WHERE t.user_id_=? AND t.project_id_=? AND t.public_id=? AND c.public_id=? FOR UPDATE");$s->bind_param('iiss',$u,$p,$taskPublic,$cyclePublic);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();if(!$r||(string)$r['cycle_status']!=='active'||(string)$r['mode']==='disabled'||(string)$r['policy_status']!=='active')throw new TaskValidationException('continuation_root_scope_invalid');$s=$this->p('INSERT INTO ProjectAutonomyCycleTasks(cycle_id_,user_id_,project_id_,task_id_,depth) VALUES(?,?,?,?,0) ON DUPLICATE KEY UPDATE id_=LAST_INSERT_ID(id_)');$s->bind_param('iiii',$r['cycle_id'],$u,$p,$r['task_id']);$this->x($s);$s->close();$s=$this->p('SELECT cycle_id_,depth FROM ProjectAutonomyCycleTasks WHERE task_id_=? AND user_id_=? LIMIT 1 FOR UPDATE');$s->bind_param('ii',$r['task_id'],$u);$this->x($s);$membership=$s->get_result()->fetch_assoc();$s->close();if(!$membership||(int)$membership['cycle_id_']!==(int)$r['cycle_id']||(int)$membership['depth']!==0)throw new TaskConcurrencyException('continuation_root_already_enrolled');$this->db->commit();return['task_public_id'=>$taskPublic,'cycle_public_id'=>$cyclePublic,'depth'=>0];}catch(Throwable$e){$this->db->rollback();throw$e;}}
 public function answer(int$u,int$p,string$task,string$public,string$answer):array{$this->db->begin_transaction();try{$s=$this->p("SELECT pc.*,t.id_ source_task_id,t.status source_task_status FROM PostTaskContinuations pc JOIN Tasks t ON t.id_=pc.source_task_id_ AND t.user_id_=pc.user_id_ AND t.project_id_=pc.project_id_ WHERE pc.user_id_=? AND pc.project_id_=? AND t.public_id=? AND pc.public_id=? FOR UPDATE");$s->bind_param('iiss',$u,$p,$task,$public);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();if(!$r)throw new TaskNotFoundException('continuation_not_found');if((string)$r['source_task_status']==='cancelled')throw new TaskTransitionException('continuation_source_cancelled');if($r['answer']!==null){if(hash_equals((string)$r['answer'],$answer)){$this->db->commit();return['public_id'=>$public,'status'=>(string)$r['status'],'answered_at'=>$r['answered_at'],'idempotent'=>true];}throw new TaskConcurrencyException('continuation_answer_conflict');}if($r['status']!=='waiting_user')throw new TaskTransitionException('continuation_not_waiting_user');$s=$this->p("UPDATE PostTaskContinuations SET answer=?,answered_at=NOW(6),answered_by_user_id_=?,status='pending',decision_json=NULL,usage_json=NULL,decision_type=NULL,next_attempt_at=NOW(6),finished_at=NULL WHERE id_=? AND status='waiting_user' AND answer IS NULL");$s->bind_param('sii',$answer,$u,$r['id_']);$this->x($s);if($s->affected_rows!==1)throw new TaskConcurrencyException('continuation_answer_conflict');$s->close();$summary='El usuario respondió la solicitud de continuidad.';$s=$this->p("INSERT INTO TaskEvents(task_id_,actor_type,event_key,summary,details_json) VALUES(?,'user','continuation_user_answered',?,JSON_OBJECT('continuation_public_id',?))");$s->bind_param('iss',$r['source_task_id'],$summary,$public);$this->x($s);$s->close();$this->db->commit();return['public_id'=>$public,'status'=>'pending','answered_at'=>gmdate('Y-m-d H:i:s.u'),'idempotent'=>false];}catch(Throwable$e){$this->db->rollback();throw$e;}}
 public function discover(int$limit):int{$limit=max(1,min(100,$limit));$reconcile="UPDATE PostTaskContinuations pc JOIN NextWorkProposals p ON p.id_=pc.proposal_id_ SET pc.status=IF(p.status='spawned','completed','failed'),pc.spawned_task_id_=p.spawned_task_id_,pc.reason_code=IF(p.status='spawned','spawned','proposal_rejected'),pc.finished_at=NOW(6) WHERE pc.status='waiting_approval' AND p.status IN ('spawned','rejected')";if(!$this->db->query($reconcile))throw new RuntimeException('continuation_reconcile_failed');$sql="SELECT x.task_id,x.user_id,x.project_id,x.cycle_id,x.terminal_status,x.depth FROM ((SELECT t.id_ task_id,t.user_id_ user_id,t.project_id_ project_id,m.cycle_id_ cycle_id,t.status terminal_status,m.depth depth FROM ProjectAutonomyCycleTasks m JOIN Tasks t ON t.id_=m.task_id_) UNION ALL (SELECT t.id_,t.user_id_,t.project_id_,p.autonomy_cycle_id_,t.status,COALESCE(parentc.depth+1,1) FROM NextWorkProposals p JOIN Tasks t ON t.id_=p.spawned_task_id_ LEFT JOIN PostTaskContinuations parentc ON parentc.autonomy_cycle_id_=p.autonomy_cycle_id_ AND parentc.source_task_id_=p.source_task_id_)) x JOIN ProjectAutonomyCycles c ON c.id_=x.cycle_id AND c.status='active' JOIN ProjectAutonomyPolicies ap ON ap.id_=c.policy_id_ AND ap.mode<>'disabled' AND ap.status='active' WHERE x.terminal_status IN ('completed','failed','cancelled') AND NOT EXISTS(SELECT 1 FROM TaskReplanRequests rr WHERE rr.task_id_=x.task_id AND rr.autonomy_cycle_id_=x.cycle_id AND rr.status IN ('checkpointed','processing','proposed','pending_approval','approved')) AND NOT EXISTS(SELECT 1 FROM PostTaskContinuations pc WHERE pc.autonomy_cycle_id_=x.cycle_id AND pc.source_task_id_=x.task_id) ORDER BY x.task_id LIMIT ?";$s=$this->p($sql);$s->bind_param('i',$limit);$this->x($s);$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$n=0;foreach($rows as$r){$depth=(int)$r['depth'];$this->assertAcyclic((int)$r['task_id']);$public=TaskPublicId::generate();$s=$this->p("INSERT IGNORE INTO PostTaskContinuations(public_id,user_id_,project_id_,source_task_id_,autonomy_cycle_id_,terminal_status,depth,status) VALUES(?,?,?,?,?,?,?,'pending')");$s->bind_param('siiiisi',$public,$r['user_id'],$r['project_id'],$r['task_id'],$r['cycle_id'],$r['terminal_status'],$depth);$this->x($s);$n+=$s->affected_rows;$s->close();}return$n;}
 public function claim(string$worker,int$lease,int$max):?array{$this->db->begin_transaction();try{$s=$this->p("SELECT pc.*,t.public_id source_task_public_id,c.public_id cycle_public_id,ap.mode autonomy_mode,ap.status policy_status,ap.max_descendant_depth FROM PostTaskContinuations pc JOIN Tasks t ON t.id_=pc.source_task_id_ JOIN ProjectAutonomyCycles c ON c.id_=pc.autonomy_cycle_id_ JOIN ProjectAutonomyPolicies ap ON ap.id_=c.policy_id_ WHERE ap.status<>'paused' AND ((pc.status='pending' AND pc.next_attempt_at<=NOW(6)) OR (pc.status='processing' AND pc.lease_expires_at<NOW(6))) AND pc.attempt_count<? ORDER BY pc.next_attempt_at,pc.id_ LIMIT 1 FOR UPDATE SKIP LOCKED");$s->bind_param('i',$max);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();if(!$r){$this->db->commit();return null;}$token=TaskWorkerConfig::leaseToken();$id=(int)$r['id_'];$s=$this->p("UPDATE PostTaskContinuations SET status='processing',worker_id=?,lease_token=?,lease_expires_at=DATE_ADD(NOW(6),INTERVAL ? SECOND),started_at=COALESCE(started_at,NOW(6)),attempt_count=attempt_count+1 WHERE id_=?");$s->bind_param('ssii',$worker,$token,$lease,$id);$this->x($s);$s->close();$this->db->commit();$r['lease_token']=$token;$r['worker_id']=$worker;$r['attempt_count']=(int)$r['attempt_count']+1;return$r;}catch(Throwable$e){$this->db->rollback();throw$e;}}
 public function recordEvaluation(array$c,NextWorkEvaluationResult$r):void{$decision=json_encode($r->decision->toArray(),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);$usage=json_encode($r->usage,JSON_THROW_ON_ERROR);$type=$r->decision->decision;$s=$this->p("UPDATE PostTaskContinuations SET decision_type=?,decision_json=?,usage_json=? WHERE id_=? AND worker_id=? AND lease_token=? AND status='processing'");$s->bind_param('sssiss',$type,$decision,$usage,$c['id_'],$c['worker_id'],$c['lease_token']);$this->x($s);if($s->affected_rows!==1){$s->close();throw new TaskConcurrencyException('continuation_claim_lost');}$s->close();}
 public function finish(array$c,string$status,string$decision,string$reason,string$publicReason,?string$question=null,?string$proposal=null,?string$spawned=null):void{$proposalId=$proposal===null?null:$this->proposalId((int)$c['user_id_'],$proposal);$taskId=$spawned===null?null:$this->taskId((int)$c['user_id_'],$spawned);$s=$this->p("UPDATE PostTaskContinuations SET status=?,decision_type=?,reason_code=?,public_reason=?,question=?,proposal_id_=?,spawned_task_id_=?,finished_at=NOW(6),lease_expires_at=NULL,worker_id=NULL,lease_token=NULL WHERE id_=? AND worker_id=? AND lease_token=? AND status='processing'");$s->bind_param('sssssiiiss',$status,$decision,$reason,$publicReason,$question,$proposalId,$taskId,$c['id_'],$c['worker_id'],$c['lease_token']);$this->x($s);if($s->affected_rows!==1){$s->close();throw new TaskConcurrencyException('continuation_claim_lost');}$s->close();}
 public function retry(array$c,string$reason,int$max):void{$terminal=(int)$c['attempt_count']>=$max;$status=$terminal?'failed':'pending';$delay=min(300,5*(2**max(0,(int)$c['attempt_count']-1)));$s=$this->p("UPDATE PostTaskContinuations SET status=?,reason_code=?,next_attempt_at=DATE_ADD(NOW(6),INTERVAL ? SECOND),finished_at=IF(?='failed',NOW(6),NULL),lease_expires_at=NULL,worker_id=NULL,lease_token=NULL WHERE id_=? AND worker_id=? AND lease_token=? AND status='processing'");$s->bind_param('ssisiss',$status,$reason,$delay,$status,$c['id_'],$c['worker_id'],$c['lease_token']);$this->x($s);$s->close();}
 public function closeCycle(int$u,int$p,string$public,string$status):void{$s=$this->p("UPDATE ProjectAutonomyCycles SET status=?,finished_at=NOW(6),lock_version=lock_version+1 WHERE user_id_=? AND project_id_=? AND public_id=? AND status='active'");$s->bind_param('siis',$status,$u,$p,$public);$this->x($s);$s->close();}
 public function event(array$c,string$key,string$summary):void{$summary=mb_substr($summary,0,255);$s=$this->p("INSERT INTO TaskEvents(task_id_,actor_type,event_key,summary,details_json) VALUES(?,'system',?,?,JSON_OBJECT('continuation_public_id',?))");$s->bind_param('isss',$c['source_task_id_'],$key,$summary,$c['public_id']);$this->x($s);$s->close();}
 private function assertAcyclic(int$id):void{$this->depth($id);}
 private function depth(int$id):int{$d=0;$seen=[];while($id>0){if(isset($seen[$id])||$d>10)throw new TaskValidationException('continuation_lineage_invalid');$seen[$id]=1;$s=$this->p('SELECT parent_task_id_ FROM Tasks WHERE id_=?');$s->bind_param('i',$id);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();$id=(int)($r['parent_task_id_']??0);if($id>0)$d++;}return$d;}
 private function proposalId(int$u,string$public):int{$s=$this->p('SELECT id_ FROM NextWorkProposals WHERE user_id_=? AND public_id=?');$s->bind_param('is',$u,$public);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();return(int)($r['id_']??throw new TaskValidationException('continuation_proposal_scope'));}private function taskId(int$u,string$public):int{$s=$this->p('SELECT id_ FROM Tasks WHERE user_id_=? AND public_id=?');$s->bind_param('is',$u,$public);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();return(int)($r['id_']??throw new TaskValidationException('continuation_task_scope'));}
 private function p(string$q):mysqli_stmt{$s=$this->db->prepare($q);if(!$s)throw new RuntimeException('continuation_prepare_failed');return$s;}private function x(mysqli_stmt$s):void{if(!$s->execute())throw new RuntimeException('continuation_query_failed');}
}
